class Solution {
    public int chalkReplacer(int[] chalk,int k){
        long sum=0;
        for(int value:chalk)sum+=value;
        long remaining=k%sum;
        for(int i=0;i<chalk.length;i++){
            if(remaining<chalk[i])return i;
            remaining-=chalk[i];
        }
        return 0;
    }
}

code.kotlin:
class Solution {
    fun chalkReplacer(chalk:IntArray,k:Int):Int{
        val sum=chalk.sumOf{
            it.toLong()
        };
        var remaining=k%sum;
        for(i in chalk.indices){
            if(remaining<chalk[i])return i;
            remaining-=chalk[i]
        };
        return 0
    }
}

code.cpp:
class Solution {
    public: int chalkReplacer(vector<int>& chalk,int k){
        long long sum=accumulate(chalk.begin(),chalk.end(),0LL),remaining=k%sum;
        for(int i=0;i<(int)chalk.size();++i){
            if(remaining<chalk[i])return i;
            remaining-=chalk[i];
        }
        return 0;
    }
};
